// Hand-written reimplementation of PyYAML's yaml.safe_load for the common
// YAML subset. No regular expressions, no JSON, no external modules: every
// lexing and parsing step is direct character scanning.
//
// Supported: block maps/sequences by indentation, flow collections, plain /
// single-quoted / double-quoted scalars (including multi-line continuations),
// comments, blank lines, --- / ... document markers, tags, anchors/aliases,
// merge keys, block scalars (| and > with chomping/indent indicators), and
// YAML 1.1 implicit scalar resolution (null/bool/int/float/timestamp).

import { YamlTimestamp } from './yamlTypes.mjs';

const TAG_PREFIX = 'tag:yaml.org,2002:';

const NULL_WORDS = new Set(['~', 'null', 'Null', 'NULL']);

const BOOL_WORDS = new Map([
  ['yes', true], ['Yes', true], ['YES', true],
  ['no', false], ['No', false], ['NO', false],
  ['true', true], ['True', true], ['TRUE', true],
  ['false', false], ['False', false], ['FALSE', false],
  ['on', true], ['On', true], ['ON', true],
  ['off', false], ['Off', false], ['OFF', false],
]);

function fail(msg) {
  throw new Error('YAML parse error: ' + msg);
}

function hasOwn(obj, key) {
  return Object.prototype.hasOwnProperty.call(obj, key);
}

function setKey(obj, key, value) {
  if (key === '__proto__') {
    Object.defineProperty(obj, key, {
      value, enumerable: true, writable: true, configurable: true,
    });
  } else {
    obj[key] = value;
  }
}

function isDigit(c) {
  return c >= '0' && c <= '9';
}

function isHexDigit(c) {
  return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F');
}

function isFlowChar(c) {
  return c === ',' || c === '[' || c === ']' || c === '{' || c === '}';
}

function trimRightSpaces(s) {
  let end = s.length;
  while (end > 0 && (s[end - 1] === ' ' || s[end - 1] === '\t')) end--;
  return s.substring(0, end);
}

function stripUnderscores(s) {
  return s.split('_').join('');
}

// ---------------------------------------------------------------------------
// Scalar resolution (YAML 1.1 implicit typing, PyYAML rules)
// ---------------------------------------------------------------------------

function tryParseInt(text, strict) {
  let s = text;
  let neg = false;
  if (s[0] === '+') s = s.substring(1);
  else if (s[0] === '-') { neg = true; s = s.substring(1); }
  if (s === '') return { ok: false };

  const digitsOnly = (body, lo, hi) => {
    // every char is a digit in [lo,hi] or '_'; at least one digit present
    let seen = false;
    for (let k = 0; k < body.length; k++) {
      const c = body[k];
      if (c === '_') continue;
      if (c >= lo && c <= hi) { seen = true; continue; }
      return false;
    }
    return seen;
  };

  let value;
  if (s.length > 2 && s[0] === '0' && s[1] === 'b') {
    const body = s.substring(2);
    if (!digitsOnly(body, '0', '1')) return { ok: false };
    value = parseInt(stripUnderscores(body), 2);
  } else if (s.length > 2 && s[0] === '0' && s[1] === 'x') {
    const body = s.substring(2);
    let seen = false;
    for (let k = 0; k < body.length; k++) {
      const c = body[k];
      if (c === '_') continue;
      if (isHexDigit(c)) { seen = true; continue; }
      return { ok: false };
    }
    if (!seen) return { ok: false };
    value = parseInt(stripUnderscores(body), 16);
  } else if (s.indexOf(':') !== -1) {
    // sexagesimal: [-+]?[1-9][0-9_]*(:[0-5]?[0-9])+  (strict form)
    const groups = s.split(':');
    if (groups.length < 2) return { ok: false };
    value = 0;
    for (let g = 0; g < groups.length; g++) {
      const grp = groups[g];
      if (strict) {
        if (g === 0) {
          if (grp.length === 0 || grp[0] < '1' || grp[0] > '9') return { ok: false };
          for (let k = 1; k < grp.length; k++) {
            if (!isDigit(grp[k]) && grp[k] !== '_') return { ok: false };
          }
        } else {
          // [0-5]?[0-9]
          if (grp.length === 1) {
            if (!isDigit(grp[0])) return { ok: false };
          } else if (grp.length === 2) {
            if (grp[0] < '0' || grp[0] > '5' || !isDigit(grp[1])) return { ok: false };
          } else {
            return { ok: false };
          }
        }
      } else {
        if (!digitsOnly(grp, '0', '9')) return { ok: false };
      }
      value = value * 60 + parseInt(stripUnderscores(grp), 10);
    }
  } else if (s.length > 1 && s[0] === '0') {
    // octal: 0[0-7_]+
    const body = s.substring(1);
    if (!digitsOnly(body, '0', '7')) return { ok: false };
    value = parseInt(stripUnderscores(body), 8);
  } else {
    // decimal: 0 or [1-9][0-9_]*
    if (s !== '0' && (s[0] < '1' || s[0] > '9')) return { ok: false };
    if (!digitsOnly(s, '0', '9')) return { ok: false };
    value = parseInt(stripUnderscores(s), 10);
  }
  return { ok: true, value: neg ? -value : value };
}

function tryParseFloat(text, strict) {
  let s = text;
  let neg = false;
  if (s[0] === '+') s = s.substring(1);
  else if (s[0] === '-') { neg = true; s = s.substring(1); }

  if (s === '.inf' || s === '.Inf' || s === '.INF') {
    return { ok: true, value: neg ? -Infinity : Infinity };
  }
  // .nan never takes a sign in the PyYAML resolver
  if (text === '.nan' || text === '.NaN' || text === '.NAN') {
    return { ok: true, value: NaN };
  }
  if (s === '') return { ok: false };

  if (s.indexOf(':') !== -1) {
    // sexagesimal float: [0-9][0-9_]*(:[0-5]?[0-9])+\.[0-9_]*
    const groups = s.split(':');
    if (groups.length < 2) return { ok: false };
    const last = groups[groups.length - 1];
    if (last.indexOf('.') === -1) return { ok: false };
    let value = 0;
    for (let g = 0; g < groups.length; g++) {
      const grp = groups[g];
      if (strict) {
        if (g === 0) {
          if (grp.length === 0 || !isDigit(grp[0])) return { ok: false };
          for (let k = 1; k < grp.length; k++) {
            if (!isDigit(grp[k]) && grp[k] !== '_') return { ok: false };
          }
        } else {
          // [0-5]?[0-9] with an optional .[0-9_]* tail on the last group
          let k = 0;
          if (grp[k] >= '0' && grp[k] <= '5' && isDigit(grp[k + 1])) k = 2;
          else if (isDigit(grp[k])) k = 1;
          else return { ok: false };
          if (g === groups.length - 1) {
            if (grp[k] !== '.') return { ok: false };
            k++;
            for (; k < grp.length; k++) {
              if (!isDigit(grp[k]) && grp[k] !== '_') return { ok: false };
            }
          } else if (k !== grp.length) {
            return { ok: false };
          }
        }
      }
      const num = Number(stripUnderscores(grp));
      if (Number.isNaN(num) || grp === '') return { ok: false };
      value = value * 60 + num;
    }
    return { ok: true, value: neg ? -value : value };
  }

  if (!strict) {
    // PyYAML's float constructor: float(value.replace('_', '')) — lenient,
    // accepts things like "1e3" that the resolver would leave a string.
    const clean = stripUnderscores(s);
    if (clean === '') return { ok: false };
    if (clean.indexOf('x') !== -1 || clean.indexOf('X') !== -1) return { ok: false };
    const v = Number(clean);
    if (Number.isNaN(v)) return { ok: false };
    return { ok: true, value: neg ? -v : v };
  }

  // Strict resolver forms (a dot is mandatory):
  //   A: [0-9][0-9_]*\.[0-9_]*([eE][-+]?[0-9]+)?
  //   B: \.[0-9][0-9_]*([eE][-+][0-9]+)?        (exponent sign required)
  const n = s.length;
  let i = 0;
  let digitsBefore = 0;
  while (i < n && (isDigit(s[i]) || s[i] === '_')) {
    if (isDigit(s[i])) digitsBefore++;
    i++;
  }
  let formB = false;
  if (digitsBefore > 0 && s[i] === '.') {
    i++;
  } else if (digitsBefore === 0 && s[0] === '.') {
    formB = true;
    i = 1;
    let d = 0;
    while (i < n && (isDigit(s[i]) || s[i] === '_')) {
      if (isDigit(s[i])) d++;
      i++;
    }
    if (d === 0) return { ok: false };
  } else {
    return { ok: false };
  }
  if (!formB) {
    // consume fraction digits for form A
    while (i < n && (isDigit(s[i]) || s[i] === '_')) i++;
  }
  if (i < n && (s[i] === 'e' || s[i] === 'E')) {
    i++;
    if (formB) {
      if (s[i] !== '+' && s[i] !== '-') return { ok: false };
      i++;
    } else if (s[i] === '+' || s[i] === '-') {
      i++;
    }
    let d = 0;
    while (i < n && isDigit(s[i])) { d++; i++; }
    if (d === 0) return { ok: false };
  }
  if (i !== n) return { ok: false };
  const v = Number(stripUnderscores(s));
  if (Number.isNaN(v)) return { ok: false };
  return { ok: true, value: neg ? -v : v };
}

const DAYS_IN_MONTH = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

function daysInMonth(year, month) {
  if (month === 2) {
    const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
    return leap ? 29 : 28;
  }
  return DAYS_IN_MONTH[month - 1];
}

// Returns false when the text is not timestamp-shaped, 'invalid' when it is
// shaped like a timestamp but out of range (PyYAML raises in that case), and
// true when it is a valid timestamp.
function checkTimestamp(t) {
  const n = t.length;
  let i = 0;
  const readDigits = (min, max) => {
    const start = i;
    while (i < n && isDigit(t[i]) && i - start < max) i++;
    const len = i - start;
    if (len < min) return null;
    return { value: parseInt(t.substring(start, i), 10), len };
  };

  if (n < 10 - 5) return false;
  for (let k = 0; k < 4; k++) if (!isDigit(t[k])) return false;
  const year = parseInt(t.substring(0, 4), 10);
  i = 4;
  if (t[i] !== '-') return false;
  i++;
  const monthR = readDigits(1, 2);
  if (monthR === null) return false;
  if (t[i] !== '-') return false;
  i++;
  const dayR = readDigits(1, 2);
  if (dayR === null) return false;

  if (i === n) {
    // date-only form requires exactly two-digit month and day
    if (monthR.len !== 2 || dayR.len !== 2) return false;
    return validDate(year, monthR.value, dayR.value) ? true : 'invalid';
  }

  const sep = t[i];
  if (sep === 'T' || sep === 't') {
    i++;
  } else if (sep === ' ' || sep === '\t') {
    while (t[i] === ' ' || t[i] === '\t') i++;
  } else {
    return false;
  }

  const hourR = readDigits(1, 2);
  if (hourR === null) return false;
  if (t[i] !== ':') return false;
  i++;
  const minR = readDigits(2, 2);
  if (minR === null) return false;
  if (t[i] !== ':') return false;
  i++;
  const secR = readDigits(2, 2);
  if (secR === null) return false;
  if (t[i] === '.') {
    i++;
    while (i < n && isDigit(t[i])) i++;
  }
  while (t[i] === ' ' || t[i] === '\t') i++;
  let tzHour = 0;
  let tzMin = 0;
  if (i < n) {
    if (t[i] === 'Z') {
      i++;
    } else if (t[i] === '+' || t[i] === '-') {
      i++;
      const tzh = readDigits(1, 2);
      if (tzh === null) return false;
      tzHour = tzh.value;
      if (t[i] === ':') {
        i++;
        const tzm = readDigits(2, 2);
        if (tzm === null) return false;
        tzMin = tzm.value;
      }
    } else {
      return false;
    }
  }
  if (i !== n) return false;

  if (!validDate(year, monthR.value, dayR.value)) return 'invalid';
  if (hourR.value > 23 || minR.value > 59 || secR.value > 59) return 'invalid';
  if (tzHour > 23 || tzMin > 59) return 'invalid';
  return true;
}

function validDate(year, month, day) {
  if (year < 1) return false;
  if (month < 1 || month > 12) return false;
  if (day < 1 || day > daysInMonth(year, month)) return false;
  return true;
}

// ---------------------------------------------------------------------------
// Escape decoding for double-quoted scalars
// ---------------------------------------------------------------------------

// Reads one escape body at str[p] (the char right after the backslash).
// Returns { value, next } where next is the index past the escape.
function escapeAt(str, p) {
  const c = str[p];
  switch (c) {
    case '0': return { value: '\0', next: p + 1 };
    case 'a': return { value: '\x07', next: p + 1 };
    case 'b': return { value: '\b', next: p + 1 };
    case 't': return { value: '\t', next: p + 1 };
    case 'n': return { value: '\n', next: p + 1 };
    case 'v': return { value: '\x0b', next: p + 1 };
    case 'f': return { value: '\f', next: p + 1 };
    case 'r': return { value: '\r', next: p + 1 };
    case 'e': return { value: '\x1b', next: p + 1 };
    case '"': return { value: '"', next: p + 1 };
    case '/': return { value: '/', next: p + 1 };
    case '\\': return { value: '\\', next: p + 1 };
    case ' ': return { value: ' ', next: p + 1 };
    case '_': return { value: '\xa0', next: p + 1 };
    case 'N': return { value: '\x85', next: p + 1 };
    case 'L': return { value: '\u2028', next: p + 1 };
    case 'P': return { value: '\u2029', next: p + 1 };
    case 'x': return readHexEscape(str, p + 1, 2);
    case 'u': return readHexEscape(str, p + 1, 4);
    case 'U': return readHexEscape(str, p + 1, 8);
    default: fail('unknown escape character \\' + c);
  }
}

function readHexEscape(str, p, count) {
  let digits = '';
  for (let k = 0; k < count; k++) {
    const c = str[p + k];
    if (c === undefined || !isHexDigit(c)) fail('bad hex escape');
    digits += c;
  }
  return { value: String.fromCodePoint(parseInt(digits, 16)), next: p + count };
}

// Single-line quoted scan used for mapping keys. Returns { value, endPos }
// with endPos just past the closing quote, or null when the quote does not
// close on this line.
function scanQuotedKeyInline(content, start) {
  const quote = content[start];
  const dbl = quote === '"';
  let p = start + 1;
  let out = '';
  while (p < content.length) {
    const c = content[p];
    if (c === quote) {
      if (!dbl && content[p + 1] === quote) { out += quote; p += 2; continue; }
      return { value: out, endPos: p + 1 };
    }
    if (dbl && c === '\\') {
      const r = escapeAt(content, p + 1);
      out += r.value;
      p = r.next;
      continue;
    }
    out += c;
    p++;
  }
  return null;
}

// ---------------------------------------------------------------------------
// Parser
// ---------------------------------------------------------------------------

class Parser {
  constructor(text) {
    if (text.charCodeAt(0) === 0xFEFF) text = text.substring(1);
    text = text.split('\r\n').join('\n').split('\r').join('\n');
    if (text.indexOf('\0') !== -1) fail('unacceptable character NUL');
    this.endsWithNewline = text.length > 0 && text[text.length - 1] === '\n';
    this.lines = text.split('\n');
    if (this.endsWithNewline) this.lines.pop();
    this.i = 0; // current line index
    this.p = 0; // current column (flow scanner / quoted scanner)
    this.anchors = {};
  }

  indentOf(line) {
    let n = 0;
    while (line[n] === ' ') n++;
    if (line[n] === '\t') {
      for (let k = n; k < line.length; k++) {
        if (line[k] !== ' ' && line[k] !== '\t') fail('tab character in indentation');
      }
    }
    return n;
  }

  isBlank(line) {
    for (let k = 0; k < line.length; k++) {
      if (line[k] !== ' ' && line[k] !== '\t') return false;
    }
    return true;
  }

  isCommentLine(line) {
    let k = 0;
    while (line[k] === ' ') k++;
    return line[k] === '#';
  }

  skipWsLines() {
    while (this.i < this.lines.length) {
      const line = this.lines[this.i];
      if (this.isBlank(line) || this.isCommentLine(line)) this.i++;
      else break;
    }
  }

  isMarkerLine(line) {
    const head = line.substring(0, 3);
    if (head !== '---' && head !== '...') return false;
    return line.length === 3 || line[3] === ' ' || line[3] === '\t';
  }

  isDocStartLine(line) {
    return this.isMarkerLine(line) && line.substring(0, 3) === '---';
  }

  isDocEndLine(line) {
    return this.isMarkerLine(line) && line.substring(0, 3) === '...';
  }

  // -------------------------------------------------------------------------
  // Document level
  // -------------------------------------------------------------------------

  parse() {
    this.skipWsLines();
    let sawDirective = false;
    while (this.i < this.lines.length && this.lines[this.i][0] === '%') {
      this.i++;
      sawDirective = true;
      this.skipWsLines();
    }
    if (this.i >= this.lines.length) {
      if (sawDirective) fail('directive without document');
      return null;
    }
    if (this.isDocEndLine(this.lines[this.i])) fail('no document');

    let root;
    if (this.isDocStartLine(this.lines[this.i])) {
      const line = this.lines[this.i];
      let pos = 3;
      while (line[pos] === ' ') pos++;
      if (line[pos] === '\t') fail('tab after document marker');
      if (pos >= line.length || line[pos] === '#') {
        this.i++;
        this.skipWsLines();
        if (this.i >= this.lines.length
            || this.isDocStartLine(this.lines[this.i])
            || this.isDocEndLine(this.lines[this.i])) {
          root = null;
        } else {
          root = this.parseBlock(this.indentOf(this.lines[this.i]), -1, null, null);
        }
      } else {
        // inline node on the --- line; block collections may not start here
        this.lines[this.i] = ' '.repeat(pos) + line.substring(pos);
        root = this.parseBlock(pos, -1, 'mapValue', null);
      }
    } else {
      if (sawDirective) fail('expected document start after directives');
      root = this.parseBlock(this.indentOf(this.lines[this.i]), -1, null, null);
    }

    this.skipWsLines();
    if (this.i < this.lines.length) {
      if (this.isDocEndLine(this.lines[this.i])) {
        this.i++;
        this.skipWsLines();
        if (this.i < this.lines.length) fail('expected a single document');
      } else {
        fail('unexpected content after document');
      }
    }
    return root;
  }

  // -------------------------------------------------------------------------
  // Block level
  // -------------------------------------------------------------------------

  // Parses one node whose first line is this.lines[this.i] at the given
  // indent. parentIndent is the indentation of the enclosing block (used for
  // scalar continuations and block-scalar content detection). inlineMode is
  // 'seqItem' / 'mapValue' when the node starts mid-line; in 'mapValue' mode
  // block sequences and mappings cannot begin (`a: - b` is an error).
  parseBlock(indent, parentIndent, inlineMode, anchor) {
    const line = this.lines[this.i];
    const content = line.substring(indent);
    const c0 = content[0];
    if (c0 !== '[' && c0 !== '{' && inlineMode !== 'mapValue') {
      if (c0 === '-' && (content.length === 1 || content[1] === ' ' || content[1] === '\t')) {
        return this.parseSeq(indent, anchor);
      }
      if (this.isMapStart(content)) {
        return this.parseMap(indent, anchor);
      }
    }
    return this.parseScalarNode(indent, parentIndent, anchor);
  }

  isMapStart(content) {
    if (content[0] === '?' && (content.length === 1 || content[1] === ' ')) return true;
    return this.scanMapKey(content) !== null;
  }

  parseSeq(indent, anchor) {
    const arr = [];
    if (anchor !== null) this.anchors[anchor] = arr;
    for (;;) {
      this.skipWsLines();
      if (this.i >= this.lines.length) break;
      const line = this.lines[this.i];
      if (this.isMarkerLine(line)) break;
      if (this.indentOf(line) !== indent) break;
      const content = line.substring(indent);
      if (content[0] !== '-') break;
      if (!(content.length === 1 || content[1] === ' ' || content[1] === '\t')) break;
      if (content[1] === '\t') fail('tab after block sequence dash');
      const rest = content.substring(1);
      let j = 0;
      while (rest[j] === ' ') j++;
      let val;
      if (j >= rest.length || rest[j] === '#') {
        this.i++;
        this.skipWsLines();
        if (this.i < this.lines.length
            && !this.isMarkerLine(this.lines[this.i])
            && this.indentOf(this.lines[this.i]) > indent) {
          val = this.parseBlock(this.indentOf(this.lines[this.i]), indent, null, null);
        } else {
          val = null;
        }
      } else {
        const col = indent + 1 + j;
        this.lines[this.i] = ' '.repeat(col) + rest.substring(j);
        val = this.parseBlock(col, indent, 'seqItem', null);
      }
      arr.push(val);
    }
    return arr;
  }

  parseMap(indent, anchor) {
    const obj = {};
    if (anchor !== null) this.anchors[anchor] = obj;
    for (;;) {
      this.skipWsLines();
      if (this.i >= this.lines.length) break;
      const line = this.lines[this.i];
      if (this.isMarkerLine(line)) break;
      if (this.indentOf(line) !== indent) break;
      const content = line.substring(indent);

      if (content[0] === '?' && (content.length === 1 || content[1] === ' ' || content[1] === '\t')) {
        if (content[1] === '\t') fail('tab after explicit key indicator');
        // explicit key entry
        const rest = content.substring(1);
        let j = 0;
        while (rest[j] === ' ') j++;
        let key;
        if (j >= rest.length || rest[j] === '#') {
          this.i++;
          this.skipWsLines();
          if (this.i < this.lines.length
              && !this.isMarkerLine(this.lines[this.i])
              && this.indentOf(this.lines[this.i]) > indent) {
            key = this.parseBlock(this.indentOf(this.lines[this.i]), indent, null, null);
          } else {
            key = null;
          }
        } else {
          const col = indent + 1 + j;
          this.lines[this.i] = ' '.repeat(col) + rest.substring(j);
          key = this.parseBlock(col, indent, 'mapValue', null);
        }
        this.skipWsLines();
        let value = null;
        if (this.i < this.lines.length) {
          const l2 = this.lines[this.i];
          if (!this.isMarkerLine(l2) && this.indentOf(l2) === indent) {
            const c2 = l2.substring(indent);
            if (c2[0] === ':' && (c2.length === 1 || c2[1] === ' ' || c2[1] === '\t')) {
              if (c2[1] === '\t') fail('tab after explicit value indicator');
              value = this.parseValueRest(indent, indent + 1);
            }
          }
        }
        this.assignEntry(obj, key, value, false);
        continue;
      }

      const entry = this.scanMapKey(content);
      if (entry === null) break;
      const key = entry.style === 'quoted' ? entry.keyText : this.resolvePlain(entry.keyText);
      const isMerge = entry.style === 'plain' && entry.keyText === '<<';
      const value = this.parseValueRest(indent, indent + entry.colonPos + 1);
      this.assignEntry(obj, key, value, isMerge);
    }
    return obj;
  }

  assignEntry(obj, key, value, isMerge) {
    if (isMerge) {
      this.mergeInto(obj, value);
      return;
    }
    setKey(obj, this.keyToString(key), value);
  }

  mergeInto(obj, value) {
    if (Array.isArray(value)) {
      for (const m of value) this.mergeOne(obj, m);
    } else {
      this.mergeOne(obj, value);
    }
  }

  mergeOne(obj, m) {
    if (m === null || typeof m !== 'object' || Array.isArray(m) || m instanceof YamlTimestamp) {
      fail('merge value is not a mapping');
    }
    for (const k of Object.keys(m)) {
      if (!hasOwn(obj, k)) setKey(obj, k, m[k]);
    }
  }

  keyToString(key) {
    if (key === null) return 'null';
    if (key === true) return 'true';
    if (key === false) return 'false';
    const t = typeof key;
    if (t === 'string') return key;
    if (t === 'number') return String(key);
    if (key instanceof YamlTimestamp) return key.text;
    fail('unusable mapping key');
  }

  // Parses the value part of a mapping entry; absPos is the column just after
  // the ':' on the current line.
  parseValueRest(mapIndent, absPos) {
    const line = this.lines[this.i];
    let p = absPos;
    while (line[p] === ' ') p++;
    if (line[p] === '\t') fail('tab used as separation');
    if (p >= line.length || line[p] === '#') {
      this.i++;
      this.skipWsLines();
      if (this.i < this.lines.length && !this.isMarkerLine(this.lines[this.i])) {
        const nind = this.indentOf(this.lines[this.i]);
        if (nind > mapIndent) {
          return this.parseBlock(nind, mapIndent, null, null);
        }
        if (nind === mapIndent) {
          const c = this.lines[this.i].substring(nind);
          if (c[0] === '-' && (c.length === 1 || c[1] === ' ')) {
            return this.parseSeq(nind, null);
          }
        }
      }
      return null;
    }
    this.lines[this.i] = ' '.repeat(p) + line.substring(p);
    return this.parseBlock(p, mapIndent, 'mapValue', null);
  }

  // Finds the key/value split of a mapping entry line. Returns null when the
  // line is not a mapping entry.
  scanMapKey(content) {
    const c0 = content[0];
    if (c0 === '"' || c0 === "'") {
      const r = scanQuotedKeyInline(content, 0);
      if (r === null) return null;
      let p = r.endPos;
      while (content[p] === ' ') p++;
      if (content[p] === ':' && (p + 1 >= content.length || content[p + 1] === ' ' || content[p + 1] === '\t')) {
        return { style: 'quoted', keyText: r.value, colonPos: p };
      }
      return null;
    }
    for (let p = 0; p < content.length; p++) {
      const c = content[p];
      if (c === '#' && (p === 0 || content[p - 1] === ' ' || content[p - 1] === '\t')) return null;
      if (c === ':' && (p + 1 >= content.length || content[p + 1] === ' ' || content[p + 1] === '\t')) {
        const keyText = trimRightSpaces(content.substring(0, p));
        if (keyText === '') return null;
        return { style: 'plain', keyText, colonPos: p };
      }
    }
    return null;
  }

  // -------------------------------------------------------------------------
  // Scalar / single-node level
  // -------------------------------------------------------------------------

  parseScalarNode(indent, parentIndent, anchor) {
    const line = this.lines[this.i];
    const props = this.parsePropsOnLine(line, indent);
    if (props.anchor !== null) anchor = props.anchor;
    const tag = props.tag;
    const pos = props.pos;
    const c = line[pos];

    if (props.found && (pos >= line.length || c === '#')) {
      // tag/anchor only: the node itself starts on a following line
      this.i++;
      this.skipWsLines();
      let value;
      let got = false;
      if (this.i < this.lines.length && !this.isMarkerLine(this.lines[this.i])) {
        const nind = this.indentOf(this.lines[this.i]);
        if (nind > parentIndent) {
          value = this.parseBlock(nind, parentIndent, null, anchor);
          got = true;
        } else if (nind === parentIndent && parentIndent >= 0) {
          const cc = this.lines[this.i].substring(nind);
          if (cc[0] === '-' && (cc.length === 1 || cc[1] === ' ')) {
            value = this.parseSeq(nind, anchor);
            got = true;
          }
        }
      }
      if (!got) {
        value = this.emptyTaggedScalar(tag);
        if (anchor !== null) this.anchors[anchor] = value;
      }
      return this.applyNodeTag(tag, value);
    }

    if (pos >= line.length || c === '#') {
      // empty scalar node
      this.i++;
      if (anchor !== null) this.anchors[anchor] = null;
      return null;
    }

    if (c === '*') {
      let p = pos + 1;
      let name = '';
      while (p < line.length) {
        const ch = line[p];
        if (ch === ' ' || ch === '\t' || ch === '#' || isFlowChar(ch)) break;
        name += ch;
        p++;
      }
      if (name === '') fail('empty alias');
      let q = p;
      while (line[q] === ' ') q++;
      if (q < line.length && line[q] !== '#') fail('trailing content after alias');
      if (!hasOwn(this.anchors, name)) fail('undefined alias "' + name + '"');
      this.i++;
      return this.anchors[name];
    }

    if (c === '"' || c === "'") {
      this.p = pos;
      const text = this.scanQuoted(parentIndent);
      this.checkLineTail();
      this.i++;
      const value = (tag === null || tag === '!') ? text : this.constructTaggedScalar(tag, text);
      if (anchor !== null) this.anchors[anchor] = value;
      return value;
    }

    if (c === '[' || c === '{') {
      this.p = pos;
      const value = this.parseFlowNode(anchor, tag);
      this.checkLineTail();
      this.i++;
      return value;
    }

    if (c === '|' || c === '>') {
      const header = this.parseBlockScalarHeader(line, pos);
      this.i++;
      const text = this.readBlockScalar(parentIndent, c, header.chomp, header.digit);
      const value = (tag === null || tag === '!') ? text : this.constructTaggedScalar(tag, text);
      if (anchor !== null) this.anchors[anchor] = value;
      return value;
    }

    if (c === ',' || c === ']' || c === '}') fail('flow indicator in block context');
    if (c === '@' || c === '`') fail('reserved indicator ' + c);
    if (c === '-' || c === '?' || c === ':') {
      const nxt = pos + 1 < line.length ? line[pos + 1] : '';
      if (nxt === '' || nxt === ' ' || nxt === '\t') fail('illegal plain scalar start');
    }

    const firstText = this.scanPlainBlockLine(line, pos);
    this.i++;
    const text = this.gatherPlainContinuation(firstText, parentIndent);
    const value = (tag === null || tag === '!') ? this.resolvePlain(text) : this.constructTaggedScalar(tag, text);
    if (anchor !== null) this.anchors[anchor] = value;
    return value;
  }

  // After a quoted scalar or flow collection in block context, the rest of
  // the line must be blank or a comment.
  checkLineTail() {
    const line = this.lines[this.i];
    let q = this.p;
    while (line[q] === ' ') q++;
    if (q < line.length && line[q] !== '#') fail('trailing content after node');
  }

  parsePropsOnLine(line, start) {
    let pos = start;
    let tag = null;
    let anchor = null;
    let found = false;
    for (;;) {
      while (line[pos] === ' ') pos++;
      const c = line[pos];
      if (c === '&') {
        pos++;
        let name = '';
        while (pos < line.length) {
          const ch = line[pos];
          if (ch === ' ' || ch === '\t' || isFlowChar(ch)) break;
          name += ch;
          pos++;
        }
        if (name === '') fail('empty anchor name');
        anchor = name;
        found = true;
      } else if (c === '!') {
        const nxt = line[pos + 1];
        if (nxt === '!') {
          pos += 2;
          let s = '';
          while (pos < line.length) {
            const ch = line[pos];
            if (ch === ' ' || ch === '\t' || isFlowChar(ch)) break;
            s += ch;
            pos++;
          }
          if (s === '') fail('empty tag suffix');
          tag = TAG_PREFIX + s;
        } else if (nxt === '<') {
          const end = line.indexOf('>', pos + 2);
          if (end === -1) fail('unterminated verbatim tag');
          tag = line.substring(pos + 2, end);
          pos = end + 1;
        } else if (nxt === undefined || nxt === ' ' || nxt === '\t') {
          tag = '!';
          pos++;
        } else {
          pos++;
          let s = '';
          while (pos < line.length) {
            const ch = line[pos];
            if (ch === ' ' || ch === '\t' || isFlowChar(ch)) break;
            s += ch;
            pos++;
          }
          tag = '!' + s;
        }
        found = true;
      } else {
        break;
      }
    }
    return { tag, anchor, pos, found };
  }

  // Scans one line of a block-context plain scalar starting at pos.
  scanPlainBlockLine(line, pos) {
    let out = '';
    let p = pos;
    while (p < line.length) {
      const c = line[p];
      if (c === '#') {
        const prev = p > 0 ? line[p - 1] : ' ';
        if (p === pos || prev === ' ' || prev === '\t') break;
      }
      if (c === ':') {
        const nxt = p + 1 < line.length ? line[p + 1] : '';
        if (nxt === '' || nxt === ' ' || nxt === '\t') {
          fail('mapping values are not allowed here');
        }
      }
      out += c;
      p++;
    }
    return trimRightSpaces(out);
  }

  gatherPlainContinuation(firstText, parentIndent) {
    let text = firstText;
    let blanks = 0;
    for (;;) {
      if (this.i >= this.lines.length) break;
      const line = this.lines[this.i];
      if (this.isBlank(line)) { blanks++; this.i++; continue; }
      if (this.isCommentLine(line)) { this.i++; continue; }
      if (this.isMarkerLine(line)) break;
      const ind = this.indentOf(line);
      if (ind <= parentIndent) break;
      const part = this.scanPlainBlockLine(line, ind);
      text += blanks > 0 ? '\n'.repeat(blanks) : ' ';
      text += part;
      blanks = 0;
      this.i++;
    }
    return text;
  }

  // -------------------------------------------------------------------------
  // Quoted scalars (shared by block and flow contexts)
  // -------------------------------------------------------------------------

  // Scans a quoted scalar starting at this.lines[this.i][this.p]; advances
  // this.i/this.p past the closing quote. parentIndent is the enclosing block
  // indent in block context, or null inside flow collections.
  scanQuoted(parentIndent) {
    const quote = this.lines[this.i][this.p];
    const dbl = quote === '"';
    this.p++;
    const segs = [];
    const folds = [];
    let cur = '';
    let escBreak = false;
    for (;;) {
      if (this.i >= this.lines.length) fail('unterminated quoted scalar');
      const line = this.lines[this.i];
      let closed = false;
      while (this.p < line.length) {
        const c = line[this.p];
        if (c === quote) {
          if (!dbl && line[this.p + 1] === quote) { cur += quote; this.p += 2; continue; }
          this.p++;
          closed = true;
          break;
        }
        if (dbl && c === '\\') {
          this.p++;
          if (this.p >= line.length) { escBreak = true; break; }
          const r = escapeAt(line, this.p);
          cur += r.value;
          this.p = r.next;
          continue;
        }
        cur += c;
        this.p++;
      }
      if (closed) {
        segs.push(cur);
        let out = segs[0];
        for (let k = 1; k < segs.length; k++) out += folds[k - 1] + segs[k];
        return out;
      }
      segs.push(escBreak ? cur : trimRightSpaces(cur));
      cur = '';
      this.i++;
      this.p = 0;
      let blanks = 0;
      for (;;) {
        if (this.i >= this.lines.length) fail('unterminated quoted scalar');
        const l = this.lines[this.i];
        if (this.isBlank(l)) { blanks++; this.i++; continue; }
        break;
      }
      if (parentIndent !== null && this.indentOf(this.lines[this.i]) <= parentIndent) {
        fail('unterminated quoted scalar');
      }
      folds.push(escBreak ? '' : (blanks > 0 ? '\n'.repeat(blanks) : ' '));
      escBreak = false;
      const nl = this.lines[this.i];
      while (this.p < nl.length && (nl[this.p] === ' ' || nl[this.p] === '\t')) this.p++;
    }
  }

  // -------------------------------------------------------------------------
  // Block scalars (| and >)
  // -------------------------------------------------------------------------

  parseBlockScalarHeader(line, pos) {
    let p = pos + 1;
    let chomp = null;
    let digit = null;
    for (;;) {
      const c = line[p];
      if (c === undefined) break;
      if (c === '+' || c === '-') {
        if (chomp !== null) fail('duplicate chomping indicator');
        chomp = c;
        p++;
        continue;
      }
      if (c >= '1' && c <= '9') {
        if (digit !== null) fail('duplicate indent indicator');
        digit = c.charCodeAt(0) - 48;
        p++;
        continue;
      }
      if (c === ' ') {
        p++;
        while (line[p] === ' ') p++;
        if (line[p] !== undefined && line[p] !== '#') fail('junk in block scalar header');
        break;
      }
      if (c === '#') break;
      fail('bad block scalar header');
    }
    return { chomp, digit };
  }

  readBlockScalar(parentIndent, style, chomp, digit) {
    let contentIndent;
    if (digit !== null) {
      contentIndent = (parentIndent > 0 ? parentIndent : 0) + digit;
    } else {
      let j = this.i;
      while (j < this.lines.length && this.isBlank(this.lines[j])) j++;
      if (j < this.lines.length
          && !this.isMarkerLine(this.lines[j])
          && this.indentOf(this.lines[j]) > parentIndent) {
        contentIndent = this.indentOf(this.lines[j]);
      } else {
        // empty block scalar; leading blank lines are swallowed
        this.i = j;
        return '';
      }
    }
    const parts = [];
    while (this.i < this.lines.length) {
      const line = this.lines[this.i];
      if (this.isMarkerLine(line)) break;
      if (this.isBlank(line)) {
        parts.push({ blank: true, text: '', more: false });
        this.i++;
        continue;
      }
      const ind = this.indentOf(line);
      if (ind < contentIndent) break;
      parts.push({ blank: false, text: line.substring(contentIndent), more: ind > contentIndent });
      this.i++;
    }
    const finalBreak = this.i < this.lines.length || this.endsWithNewline;

    let raw;
    if (style === '|') {
      raw = '';
      for (let k = 0; k < parts.length; k++) {
        if (k > 0) raw += '\n';
        raw += parts[k].text;
      }
      if (parts.length > 0 && finalBreak) raw += '\n';
    } else {
      // folded: break before a blank line -> '\n', after a blank line -> '',
      // adjacent to a more-indented line -> '\n', otherwise a space.
      raw = '';
      for (let k = 0; k < parts.length; k++) {
        raw += parts[k].text;
        if (k < parts.length - 1) {
          const nxt = parts[k + 1];
          if (nxt.blank) raw += '\n';
          else if (parts[k].blank) raw += '';
          else if (parts[k].more || nxt.more) raw += '\n';
          else raw += ' ';
        }
      }
      if (parts.length > 0 && finalBreak) raw += '\n';
    }

    if (chomp === '+') return raw;
    // strip trailing line breaks
    let end = raw.length;
    while (end > 0 && raw[end - 1] === '\n') end--;
    const stripped = raw.substring(0, end);
    if (chomp === '-') return stripped;
    // clip: keep a single trailing break if there was any
    return end < raw.length ? stripped + '\n' : raw;
  }

  // -------------------------------------------------------------------------
  // Flow collections
  // -------------------------------------------------------------------------

  flowPeek() {
    if (this.i >= this.lines.length) return undefined;
    return this.lines[this.i][this.p];
  }

  skipFlowWs() {
    for (;;) {
      if (this.i >= this.lines.length) return;
      const line = this.lines[this.i];
      if (this.p >= line.length) { this.i++; this.p = 0; continue; }
      const c = line[this.p];
      if (c === ' ' || c === '\t') { this.p++; continue; }
      if (c === '#') { this.i++; this.p = 0; continue; }
      return;
    }
  }

  parsePropsFlow() {
    let tag = null;
    let anchor = null;
    const line = this.lines[this.i];
    for (;;) {
      while (this.p < line.length && (line[this.p] === ' ' || line[this.p] === '\t')) this.p++;
      const c = line[this.p];
      if (c === '&') {
        this.p++;
        let name = '';
        while (this.p < line.length) {
          const ch = line[this.p];
          if (ch === ' ' || ch === '\t' || isFlowChar(ch)) break;
          name += ch;
          this.p++;
        }
        if (name === '') fail('empty anchor name');
        anchor = name;
      } else if (c === '!') {
        const nxt = line[this.p + 1];
        if (nxt === '!') {
          this.p += 2;
          let s = '';
          while (this.p < line.length) {
            const ch = line[this.p];
            if (ch === ' ' || ch === '\t' || isFlowChar(ch)) break;
            s += ch;
            this.p++;
          }
          if (s === '') fail('empty tag suffix');
          tag = TAG_PREFIX + s;
        } else if (nxt === '<') {
          const end = line.indexOf('>', this.p + 2);
          if (end === -1) fail('unterminated verbatim tag');
          tag = line.substring(this.p + 2, end);
          this.p = end + 1;
        } else if (nxt === undefined || nxt === ' ' || nxt === '\t' || isFlowChar(nxt)) {
          tag = '!';
          this.p++;
        } else {
          this.p++;
          let s = '';
          while (this.p < line.length) {
            const ch = line[this.p];
            if (ch === ' ' || ch === '\t' || isFlowChar(ch)) break;
            s += ch;
            this.p++;
          }
          tag = '!' + s;
        }
      } else {
        break;
      }
    }
    return { tag, anchor };
  }

  parseFlowNode(inAnchor, inTag) {
    this.skipFlowWs();
    if (this.i >= this.lines.length) fail('unexpected end of input inside flow collection');
    const props = this.parsePropsFlow();
    const anchor = props.anchor !== null ? props.anchor : inAnchor;
    const tag = props.tag !== null ? props.tag : inTag;
    const c = this.flowPeek();

    if (c === '[') {
      this.p++;
      return this.applyNodeTag(tag, this.parseFlowSeq(anchor));
    }
    if (c === '{') {
      this.p++;
      return this.applyNodeTag(tag, this.parseFlowMap(anchor));
    }
    if (c === '*') {
      this.p++;
      let name = '';
      const line = this.lines[this.i];
      while (this.p < line.length) {
        const ch = line[this.p];
        if (ch === ' ' || ch === '\t' || isFlowChar(ch)) break;
        name += ch;
        this.p++;
      }
      if (name === '') fail('empty alias');
      if (!hasOwn(this.anchors, name)) fail('undefined alias "' + name + '"');
      return this.anchors[name];
    }
    if (c === '"' || c === "'") {
      const text = this.scanQuoted(null);
      const value = (tag === null || tag === '!') ? text : this.constructTaggedScalar(tag, text);
      if (anchor !== null) this.anchors[anchor] = value;
      return value;
    }
    if (c === '|' || c === '>') fail('block scalar not allowed in flow context');
    if (c === ',' || c === ']' || c === '}') fail('expected a flow node');
    const text = this.scanPlainFlow();
    if (text === '') fail('expected a flow node');
    const value = (tag === null || tag === '!') ? this.resolvePlain(text) : this.constructTaggedScalar(tag, text);
    if (anchor !== null) this.anchors[anchor] = value;
    return value;
  }

  parseFlowSeq(anchor) {
    const arr = [];
    if (anchor !== null) this.anchors[anchor] = arr;
    this.skipFlowWs();
    if (this.flowPeek() === ']') { this.p++; return arr; }
    for (;;) {
      this.skipFlowWs();
      let item;
      const pc = this.flowPeek();
      const pcNext = this.i < this.lines.length ? this.lines[this.i][this.p + 1] : undefined;
      if (pc === '?' && (pcNext === undefined || pcNext === ' ' || pcNext === '\t' || isFlowChar(pcNext))) {
        // explicit compact mapping entry: [? key : value]
        this.p++;
        const key = this.parseFlowNode(null, null);
        this.skipFlowWs();
        if (this.flowPeek() !== ':') fail('expected : in compact mapping');
        this.p++;
        this.skipFlowWs();
        const vc = this.flowPeek();
        const v = (vc === undefined || vc === ',' || vc === ']') ? null : this.parseFlowNode(null, null);
        item = {};
        setKey(item, this.keyToString(key), v);
      } else {
        item = this.parseFlowNode(null, null);
        this.skipFlowWs();
        if (this.flowPeek() === ':') {
          // compact mapping entry: [key: value]
          this.p++;
          this.skipFlowWs();
          const vc = this.flowPeek();
          const v = (vc === undefined || vc === ',' || vc === ']') ? null : this.parseFlowNode(null, null);
          const m = {};
          setKey(m, this.keyToString(item), v);
          item = m;
        }
      }
      arr.push(item);
      this.skipFlowWs();
      const c = this.flowPeek();
      if (c === ',') {
        this.p++;
        this.skipFlowWs();
        if (this.flowPeek() === ']') { this.p++; return arr; }
        continue;
      }
      if (c === ']') { this.p++; return arr; }
      fail('expected , or ] in flow sequence');
    }
  }

  parseFlowMap(anchor) {
    const obj = {};
    if (anchor !== null) this.anchors[anchor] = obj;
    this.skipFlowWs();
    if (this.flowPeek() === '}') { this.p++; return obj; }
    for (;;) {
      this.skipFlowWs();
      const pc = this.flowPeek();
      const pcNext = this.i < this.lines.length ? this.lines[this.i][this.p + 1] : undefined;
      if (pc === '?' && (pcNext === undefined || pcNext === ' ' || pcNext === '\t' || isFlowChar(pcNext))) {
        this.p++; // explicit key indicator
      }
      const key = this.parseFlowNode(null, null);
      this.skipFlowWs();
      let value = null;
      if (this.flowPeek() === ':') {
        this.p++;
        this.skipFlowWs();
        const vc = this.flowPeek();
        value = (vc === undefined || vc === ',' || vc === '}') ? null : this.parseFlowNode(null, null);
      }
      if (key === '<<') this.mergeInto(obj, value);
      else setKey(obj, this.keyToString(key), value);
      this.skipFlowWs();
      const c = this.flowPeek();
      if (c === ',') {
        this.p++;
        this.skipFlowWs();
        if (this.flowPeek() === '}') { this.p++; return obj; }
        continue;
      }
      if (c === '}') { this.p++; return obj; }
      fail('expected , or } in flow mapping');
    }
  }

  scanPlainFlow() {
    const segs = [];
    const folds = [];
    let cur = '';
    for (;;) {
      if (this.i >= this.lines.length) break;
      const line = this.lines[this.i];
      if (this.p >= line.length) {
        // line break inside a flow plain scalar: fold
        segs.push(trimRightSpaces(cur));
        cur = '';
        this.i++;
        this.p = 0;
        let blanks = 0;
        for (;;) {
          if (this.i >= this.lines.length) break;
          const l = this.lines[this.i];
          if (this.isBlank(l)) { blanks++; this.i++; continue; }
          if (this.isCommentLine(l)) { this.i++; continue; }
          break;
        }
        if (this.i >= this.lines.length) break;
        folds.push(blanks > 0 ? '\n'.repeat(blanks) : ' ');
        const nl = this.lines[this.i];
        while (this.p < nl.length && (nl[this.p] === ' ' || nl[this.p] === '\t')) this.p++;
        continue;
      }
      const c = line[this.p];
      if (isFlowChar(c)) break;
      if (c === ':') {
        const nxt = this.p + 1 < line.length ? line[this.p + 1] : undefined;
        if (nxt === undefined || nxt === ' ' || nxt === '\t' || isFlowChar(nxt)) break;
        cur += c;
        this.p++;
        continue;
      }
      if (c === '#') {
        const prev = this.p > 0 ? line[this.p - 1] : ' ';
        if (prev === ' ' || prev === '\t') {
          this.p = line.length; // comment runs to end of line
          continue;
        }
        cur += c;
        this.p++;
        continue;
      }
      cur += c;
      this.p++;
    }
    segs.push(trimRightSpaces(cur));
    let out = segs[0];
    for (let k = 1; k < segs.length; k++) out += folds[k - 1] + segs[k];
    return out;
  }

  // -------------------------------------------------------------------------
  // Scalar construction and tags
  // -------------------------------------------------------------------------

  resolvePlain(text) {
    if (text === '' || NULL_WORDS.has(text)) return null;
    if (BOOL_WORDS.has(text)) return BOOL_WORDS.get(text);
    const ti = tryParseInt(text, true);
    if (ti.ok) return ti.value;
    const tf = tryParseFloat(text, true);
    if (tf.ok) return tf.value;
    const ts = checkTimestamp(text);
    if (ts === 'invalid') fail('invalid timestamp value');
    if (ts === true) return new YamlTimestamp(text);
    return text;
  }

  constructTaggedScalar(tag, text) {
    if (tag.substring(0, TAG_PREFIX.length) !== TAG_PREFIX) fail('unsupported tag ' + tag);
    const s = tag.substring(TAG_PREFIX.length);
    if (s === 'str') return text;
    if (s === 'null') return null;
    if (s === 'bool') {
      if (BOOL_WORDS.has(text)) return BOOL_WORDS.get(text);
      fail('invalid bool value ' + text);
    }
    if (s === 'int') {
      const r = tryParseInt(text, false);
      if (!r.ok) fail('invalid int value ' + text);
      return r.value;
    }
    if (s === 'float') {
      const r = tryParseFloat(text, false);
      if (!r.ok) fail('invalid float value ' + text);
      return r.value;
    }
    if (s === 'timestamp') {
      if (checkTimestamp(text) !== true) fail('invalid timestamp value ' + text);
      return new YamlTimestamp(text);
    }
    fail('unsupported tag ' + tag);
  }

  emptyTaggedScalar(tag) {
    if (tag === null || tag === '!') return null;
    if (tag === TAG_PREFIX + 'null') return null;
    if (tag === TAG_PREFIX + 'str') return '';
    fail('cannot construct ' + tag + ' from an empty scalar');
  }

  // Applies a tag to an already-built node (used when the tag sits on its own
  // line above a collection, and for flow collections).
  applyNodeTag(tag, value) {
    if (tag === null || tag === '!') return value;
    if (tag.substring(0, TAG_PREFIX.length) !== TAG_PREFIX) fail('unsupported tag ' + tag);
    const s = tag.substring(TAG_PREFIX.length);
    if (s === 'seq') {
      if (Array.isArray(value)) return value;
      fail('tag seq applied to non-sequence');
    }
    if (s === 'map') {
      if (value !== null && typeof value === 'object' && !Array.isArray(value)
          && !(value instanceof YamlTimestamp)) return value;
      fail('tag map applied to non-mapping');
    }
    if (s === 'str') {
      if (typeof value === 'string') return value;
      fail('tag str applied to non-string');
    }
    if (s === 'null') {
      if (value === null) return null;
      fail('tag null applied to non-null');
    }
    if (s === 'bool') {
      if (typeof value === 'boolean') return value;
      fail('tag bool applied to non-bool');
    }
    if (s === 'int' || s === 'float') {
      if (typeof value === 'number') return value;
      fail('tag ' + s + ' applied to non-number');
    }
    if (s === 'timestamp') {
      if (value instanceof YamlTimestamp) return value;
      fail('tag timestamp applied to non-timestamp');
    }
    fail('unsupported tag ' + tag);
  }
}

export function safeLoad(text) {
  if (typeof text !== 'string') fail('expected a string');
  const parser = new Parser(text);
  return parser.parse();
}
